const FacebookMemoryPost: React.FC<FacebookMemoryPostProps> = ({
  backgroundColor = "#18191A",
  transparentBackground = false,
  durationInSeconds = 10,
  cardColor = "#242526",
  authorName = "Clarence Kitt",
  timeAgo = "11 years ago",
  postText = 'Umm...my face when I\'m reading some Bloomberg article and I see it discuss a boy named "Clarence". I\'m like "Okay". Then I read on and I realise it\'s me. I CANNOT.',
  avatarImage = "https://images.unsplash.com/photo-1599566150163-29194dcaad36?q=80&w=256&auto=format&fit=crop",
  likesCount = 15,
  commentsCount = 9,
  textColor = "#E4E6EB",
  subTextColor = "#B0B3B8",
  accentColor = "#2D88FF",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animations
  const entranceSpring = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8, stiffness: 120 },
  });

  const cardY = interpolate(entranceSpring, [0, 1], [150, 0]);
  const cardScale = interpolate(entranceSpring, [0, 1], [0.85, 1]);
  const cardOpacity = interpolate(entranceSpring, [0, 1], [0, 1]);

  // Staggered internal elements
  const memoryOpacity = spring({
    fps,
    frame: frame - 5,
    config: { damping: 20 }, // Smooth, elegant fade instead of bouncy pop
  });

  const memoryGlowRadius = interpolate(Math.sin(frame / 15), [-1, 1], [4, 12]);

  const headerOpacity = spring({
    fps,
    frame: frame - 5,
    config: { damping: 20 },
  });
  
  const textOpacity = spring({
    fps,
    frame: frame - 10,
    config: { damping: 20 },
  });

  const footerOpacity = spring({
    fps,
    frame: frame - 15,
    config: { damping: 20 },
  });

  // Typewriter Calculations with Pause Detection
  const typingStartFrame = 25;
  const typingDuration = 60; // 2 seconds at 30fps
  let charsToShow = 0;

  const pausePhrase = "I CANNOT";
  const pauseIndex = postText.lastIndexOf(pausePhrase);

  if (pauseIndex > 0) {
    // Dynamic typing speed based on where the pause happens
    const fraction = pauseIndex / postText.length;
    
    // Ensure monotonically increasing ranges
    const frameAtPause = typingStartFrame + Math.max(1, typingDuration * fraction);
    const pauseFrames = 45; // 1.5 seconds pause
    const frameResume = frameAtPause + pauseFrames;
    const frameEnd = frameResume + Math.max(1, typingDuration * (1 - fraction));

    charsToShow = Math.floor(
      interpolate(
        frame,
        [typingStartFrame, frameAtPause, frameResume, frameEnd],
        [0, pauseIndex, pauseIndex, postText.length],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      )
    );
  } else {
    charsToShow = Math.floor(
      interpolate(
        frame,
        [typingStartFrame, typingStartFrame + typingDuration],
        [0, postText.length],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      )
    );
  }
  
  const displayedText = postText.slice(0, charsToShow);
  const isTypingOrPaused = frame >= typingStartFrame && charsToShow < postText.length;
  const showCursor = isTypingOrPaused || (charsToShow === 0 && frame > 10);

  // Responsive scaling
  const isVertical = height > width;
  const cardWidth = isVertical ? width * 0.9 : Math.min(width * 0.8, 800);
  const baseFontSize = isVertical ? 28 : 20;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          position: "relative",
          width: cardWidth,
          backgroundColor: cardColor,
          borderRadius: 16,
          padding: isVertical ? 40 : 24,
          display: "flex",
          flexDirection: "column",
          transform: `translateY(${cardY}px) scale(${cardScale})`,
          opacity: cardOpacity,
          boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
          border: `1px solid rgba(255,255,255,0.05)`,
          transition: "none",
          overflow: "hidden", // Ensures internal glows don't bleed out
        }}
      >
        {/* Animated Background Glows - Increased Contrast & Tighter Blur */}
        <div style={{
          position: "absolute",
          top: "-20%",
          left: "-20%",
          width: "60%",
          height: "60%",
          backgroundColor: accentColor,
          opacity: 0.35,
          filter: "blur(60px)",
          transform: `scale(${interpolate(Math.sin(frame / 20), [-1, 1], [0.9, 1.2])})`,
          pointerEvents: "none",
          zIndex: 0,
          borderRadius: "50%",
        }} />
        <div style={{
          position: "absolute",
          bottom: "-20%",
          right: "-20%",
          width: "70%",
          height: "70%",
          backgroundColor: textColor,
          opacity: 0.15,
          filter: "blur(60px)",
          transform: `scale(${interpolate(Math.cos(frame / 15), [-1, 1], [0.9, 1.2])})`,
          pointerEvents: "none",
          zIndex: 0,
          borderRadius: "50%",
        }} />

        {/* Inner Content Wrapper */}
        <div style={{ position: "relative", zIndex: 1, display: "flex", flexDirection: "column" }}>
          
          {/* Memory Header (Elegant Glow) */}
          <div
            style={{
              opacity: memoryOpacity,
              display: "flex",
              alignItems: "center",
              gap: 12,
              marginBottom: 20,
              color: textColor, // Shifted to standard text color to better highlight the glow
              textShadow: `0 0 ${memoryGlowRadius}px ${accentColor}`,
              fontSize: baseFontSize * 0.8,
              fontWeight: 500,
              textTransform: "uppercase",
              letterSpacing: 1.5,
              transition: "none",
            }}
          >
            <svg 
              width={baseFontSize} 
              height={baseFontSize} 
              viewBox="0 0 24 24" 
              fill="currentColor"
              style={{
                filter: `drop-shadow(0 0 ${memoryGlowRadius}px ${accentColor})`
              }}
            >
              <path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8z"/><path d="M12.5 7H11v6l5.25 3.15.75-1.23-4.5-2.67z"/>
            </svg>
            Memory
          </div>

          {/* Header */}
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
              opacity: headerOpacity,
              transition: "none",
            }}
          >
            {/* Avatar Image */}
            <div
              style={{
                width: isVertical ? 80 : 50,
                height: isVertical ? 80 : 50,
                borderRadius: "50%",
                backgroundColor: "#3A3B3C",
                overflow: "hidden",
                marginRight: 16,
                flexShrink: 0,
              }}
            >
              <Img src={avatarImage} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
            </div>

            <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 4 }}>
              <span
                style={{
                  color: textColor,
                  fontWeight: 600,
                  fontSize: baseFontSize * 1.1,
                }}
              >
                {authorName}
              </span>
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  color: subTextColor,
                  fontSize: baseFontSize * 0.85,
                }}
              >
                <span>{timeAgo}</span>
                <span style={{ fontSize: baseFontSize * 0.5 }}>•</span>
                <GlobeIcon color={subTextColor} size={baseFontSize * 0.7} />
              </div>
            </div>

            <div style={{ padding: 8, marginTop: -20 }}>
              <DotsIcon color={subTextColor} size={baseFontSize * 1.2} />
            </div>
          </div>

          {/* Post Text - Typed Out with Pause */}
          <div
            style={{
              position: "relative",
              marginTop: isVertical ? 32 : 16,
              marginBottom: isVertical ? 32 : 16,
              color: textColor,
              fontSize: baseFontSize,
              lineHeight: 1.5,
              opacity: textOpacity,
              transition: "none",
              whiteSpace: "pre-wrap",
            }}
          >
            {/* Invisible placeholder guarantees card dimensions don't jump during typing */}
            <div style={{ visibility: "hidden" }}>{postText}</div>
            
            {/* Visible overlay for the typing effect */}
            <div style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%" }}>
              {displayedText}
              {showCursor && (
                <span style={{
                  display: "inline-block",
                  width: 2,
                  height: "1.2em",
                  backgroundColor: accentColor,
                  opacity: frame % 20 < 10 ? 1 : 0,
                  marginLeft: 4,
                  verticalAlign: "middle",
                  marginTop: "-0.2em",
                }} />
              )}
            </div>
          </div>

          {/* Footer Actions */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              opacity: footerOpacity,
              transition: "none",
              color: subTextColor,
              fontSize: baseFontSize * 0.9,
              fontWeight: 500,
              paddingTop: 16,
              borderTop: `1px solid ${subTextColor}20`,
            }}
          >
            {/* Left Actions */}
            <div style={{ display: "flex", gap: isVertical ? 32 : 24, alignItems: "center" }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
                <LikeOutlineIcon color={subTextColor} size={baseFontSize * 1.1} />
                <span>{likesCount}</span>
              </div>
              
              <div style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
                <CommentIcon color={subTextColor} size={baseFontSize * 1.1} />
                <span>{commentsCount}</span>
              </div>

              <div style={{ display: "flex", alignItems: "center", gap: 8, cursor: "pointer" }}>
                <ShareIcon color={subTextColor} size={baseFontSize * 1.1} />
              </div>
            </div>

            {/* Right Reaction Icon */}
            <ReactionIcon size={baseFontSize * 1.2} bg={accentColor} />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default FacebookMemoryPost;